  const snapshot=()=>setHistory(h=>rememberWorkspace(h,stateRef.current));
  const changeProject=(fn:(p:Project)=>Project, remember=true)=>{if(syncReadOnly){setMessage('项目已交接或待核验，请先下载并接管后编辑');return;}if(remember)snapshot();setWorkspace(w=>({...w,projects:w.projects.map(p=>p.id===w.activeId?{...fn(p),updatedAt:new Date().toISOString()}:p)}));setIssues([]);};
  const toast=(m:string)=>setMessage(m);
