  const recycleProject=async(target:Project)=>{const current=stateRef.current.projects.find(p=>p.id===target.id);if(!current)throw new Error('项目已不在当前工作区');await requestJson(`/api/recycle/projects/${target.id}`,{project:current});setHistory([]);setWorkspace(w=>withoutProject(w,target.id));setSelected(null);setEdgeId(null);setReviewInput(null);setResultAttemptId('');setIssues([]);setTab('overview');window.dispatchEvent(new CustomEvent('fpilot:history-changed',{detail:{kind:'projects',id:target.id,action:'recycle'}}));toast('项目与相关记录已移入回收站，可恢复');};
  const restoreProject=async(id:string)=>{if(stateRef.current.projects.some(p=>p.id===id))throw new Error('同 ID 项目已存在，请先处理重复项目');const data=await requestJson(`/api/recycle/projects/${id}`,undefined,'DELETE');snapshot();setWorkspace(w=>({...w,activeId:id,projects:[...w.projects,data.project]}));setAttemptRetry(n=>n+1);toast('项目已恢复；自动计划保持暂停');};
